<?php require __DIR__.'/head.php';?><nav class="topbar container"><a class="brand" href="<?=e(url())?>">a. agendashops</a><b>Administração da plataforma</b><form method="post" action="<?=e(url('sair'))?>"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><button class="secondary small">Sair</button></form></nav><main class="container section"><span class="eyebrow">VISÃO DA PLATAFORMA</span><h1>Estabelecimentos</h1><div class="stats-grid"><article class="stat"><span>Contas cadastradas</span><strong><?=count($establishments)?></strong></article><article class="stat"><span>Agendamentos totais</span><strong><?=array_sum(array_column($establishments,'bookings'))?></strong></article><article class="stat"><span>Contas ativas</span><strong><?=array_sum(array_column($establishments,'active'))?></strong></article><article class="stat"><span>Contas bloqueadas</span><strong><?=count($establishments)-array_sum(array_column($establishments,'active'))?></strong></article></div><section class="panel table-scroll"><table><thead><tr><th>Estabelecimento</th><th>Contato / categoria</th><th>Cadastro</th><th>Reservas</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php foreach($establishments as $est):?><tr><td><b><?=e($est['name'])?></b><small><?=e($est['address'])?></small></td><td><?=e($est['phone'])?><small><?=e($est['category'])?></small></td><td><?=date('d/m/Y',strtotime($est['created_at']))?></td><td><?=$est['bookings']?></td><td><?=$est['active']?'Ativo':'Bloqueado'?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$est['id']?>"><input type="hidden" name="active" value="<?=$est['active']?0:1?>"><button class="secondary small"><?=$est['active']?'Bloquear':'Desbloquear'?></button></form></td></tr><?php endforeach;?></tbody></table></section></main><?php require __DIR__.'/foot.php';?>
